$\triangle ABC$ and $\triangle DBC$ share $BC$. $AB = 5\ \text{cm}$, $AC = 12\ \text{cm}$, $DC = 8\ \text{cm}$, and $BD = 20\ \text{cm}$. What is the least possible integral number of centimeters in $BC$?

[asy]
size(100); import graph; currentpen = fontsize(10pt);
pair B = (0,0), C = (13,0), A = (-5,7), D = (16,10);

draw(B--A--C--cycle); draw(B--D--C);
label("$A$",A,W); label("$B$",B,W); label("$C$",C,E); label("$D$",D,E);
[/asy]

The graph of $y = f(x)$ is shown below.

[asy]
unitsize(0.5 cm);

real func(real x) {
  real y;
  if (x >= -3 && x <= 0) {y = -2 - x;}
  if (x >= 0 && x <= 2) {y = sqrt(4 - (x - 2)^2) - 2;}
  if (x >= 2 && x <= 3) {y = 2*(x - 2);}
  return(y);
}

int i, n;

for (i = -5; i <= 5; ++i) {
  draw((i,-5)--(i,5),gray(0.7));
  draw((-5,i)--(5,i),gray(0.7));
}

draw((-5,0)--(5,0),Arrows(6));
draw((0,-5)--(0,5),Arrows(6));

label("$x$", (5,0), E);
label("$y$", (0,5), N);

draw(graph(func,-3,3),red);

label("$y = f(x)$", (3,-2), UnFill);
[/asy]

Which is the graph of $y = f(x - 1)$?

[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -3 && x <= 0) {y = -2 - x;}
  if (x >= 0 && x <= 2) {y = sqrt(4 - (x - 2)^2) - 2;}
  if (x >= 2 && x <= 3) {y = 2*(x - 2);}
  return(y);
}

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
    draw(graf[n],(i,-5)--(i,5),gray(0.7));
    draw(graf[n],(-5,i)--(5,i),gray(0.7));
  }
  draw(graf[n],(-5,0)--(5,0),Arrows(6));
  draw(graf[n],(0,-5)--(0,5),Arrows(6));

  label(graf[n],"$x$", (5,0), E);
  label(graf[n],"$y$", (0,5), N);
}

draw(graf[1],shift(0,1)*graph(func,-3,3),red);
draw(graf[2],shift(-1,0)*graph(func,-3,3),red);
draw(graf[3],reflect((1,0),(1,1))*graph(func,-3,3),red);
draw(graf[4],shift(1,0)*graph(func,-3,3),red);
draw(graf[5],shift(0,-1)*graph(func,-3,3),red);

label(graf[1], "A", (0,-6));
label(graf[2], "B", (0,-6));
label(graf[3], "C", (0,-6));
label(graf[4], "D", (0,-6));
label(graf[5], "E", (0,-6));

add(graf[1]);
add(shift((12,0))*(graf[2]));
add(shift((24,0))*(graf[3]));
add(shift((6,-12))*(graf[4]));
add(shift((18,-12))*(graf[5]));
[/asy]

